template <typename REAL>
inline int
Tessellation::GetCoords(REAL coordTuples[]) const {
    int nCoords = GetBoundaryCoords(coordTuples);
    nCoords += GetInteriorCoords(coordTuples + nCoords * _coordStride);
    return nCoords;
}

