inline void VertexDescriptor::SetManifoldEdgeSharpness(int edgeIndex, float sharpness) { if (!_hasEdgeSharpness) initEdgeSharpness(); if (edgeIndex < _numFaces) { _faceEdgeSharpness[2*edgeIndex] = sharpness; } if (edgeIndex > 0) { _faceEdgeSharpness[2*edgeIndex-1] = sharpness; } else if (!IsBoundary()) { _faceEdgeSharpness[2*_numFaces-1] = sharpness; } }
inline float VertexDescriptor::GetManifoldEdgeSharpness(int edgeIndex) const { return _faceEdgeSharpness[2*edgeIndex - (edgeIndex == _numFaces)]; }
inline void VertexDescriptor::SetIncidentFaceEdgeSharpness(int faceIndex, float leadingEdgeSharpness, float trailingEdgeSharpness) { if (!_hasEdgeSharpness) initEdgeSharpness(); _faceEdgeSharpness[2*faceIndex] = leadingEdgeSharpness; _faceEdgeSharpness[2*faceIndex+1] = trailingEdgeSharpness; }
inline void VertexDescriptor::GetIncidentFaceEdgeSharpness(int faceIndex, float * leadingEdgeSharpness, float * trailingEdgeSharpness) const { *leadingEdgeSharpness  = _faceEdgeSharpness[2*faceIndex]; *trailingEdgeSharpness = _faceEdgeSharpness[2*faceIndex+1]; }

